using DimensionalQuantities.Roslyn.Discovery;

namespace DimensionalQuantities.Roslyn.Generators;

internal static class ArithmeticSourceEmitter
{
	public static string Emit(QuantityGenerationPlan plan)
	{
		string operators = string.Join("\n\n", plan.Operations.Select(operation => RenderOperator(operation, plan))).Replace("\n", "\n\t");
		return $$"""
			// <auto-generated />
			namespace DimensionalQuantities.Generated;

			internal static class ArithmeticExtensions
			{
				{{operators}}
			}
			""";
	}

	private static string RenderOperator(ArithmeticOperation operation, QuantityGenerationPlan plan)
	{
		string right = plan.GetQuantityName(operation.Right);
		if (operation.Kind == ArithmeticOperationKind.Multiply && operation.Result == default)
		{
			string cancellingLeft = plan.GetQuantityName(operation.Left);
			return $$"""
				extension({{cancellingLeft}})
				{
					public static double operator *({{cancellingLeft}} left, {{right}} right) =>
						left.AsSiBaseUnit() * right.AsSiBaseUnit();
				}
				""";
		}

		string result = plan.GetQuantityName(operation.Result);
		if (operation.Kind == ArithmeticOperationKind.ScalarDivide)
		{
			return $$"""
				extension({{right}})
				{
					public static {{result}} operator /(double left, {{right}} right) =>
						{{result}}.FromSiBaseUnit(left / right.AsSiBaseUnit());
				}
				""";
		}

		string left = plan.GetQuantityName(operation.Left);
		string symbol = operation.Kind == ArithmeticOperationKind.Multiply ? "*" : "/";
		return $$"""
			extension({{left}})
			{
				public static {{result}} operator {{symbol}}({{left}} left, {{right}} right) =>
					{{result}}.FromSiBaseUnit(left.AsSiBaseUnit() {{symbol}} right.AsSiBaseUnit());
			}
			""";
	}
}
